const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const robinsonCrusoe = ee.Geometry.Point([-78.85, -33.64]).buffer(1000); // Buffer of 1km
    const santaClara = ee.Geometry.Point([-79.00, -33.70]).buffer(500); // Smaller island, smaller buffer
    const timePeriod = {
        start: '2018-11-01',
        end: '2018-11-30'
    };

    // 2. Data Acquisition & Processing Function
    const getNdvi = function(geometry, name) {
        // Cloud mask function for Sentinel-2
        const maskS2clouds = function(image) {
            const qa = image.select('QA60');
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                qa.bitwiseAnd(cirrusBitMask).eq(0));
            return image.updateMask(mask).divide(10000)
                .select("B[2-8]")
                .copyProperties(image, ["system:time_start"]);
        };

        let collection = ee.ImageCollection('COPERNICUS/S2_SR')
            .filterDate(timePeriod.start, timePeriod.end)
            .filterBounds(geometry)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

        const collectionSize = collection.size().getInfo();
        if (collectionSize === 0) {
            return {size: 0, ndvi: null, pixels: null};
        }

        const image = collection.map(maskS2clouds)
            .median()
            .normalizedDifference(['B8', 'B4'])
            .rename('NDVI');

        const stats = image.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 30,
            maxPixels: 1e9
        });

        return {size: collectionSize, ndvi: stats.get('NDVI_mean'), pixels: stats.get('NDVI_count')};
    };

    // 3. Calculation for each island
    const robinsonData = getNdvi(robinsonCrusoe, 'Robinson Crusoe');
    const santaClaraData = getNdvi(santaClara, 'Santa Clara');

    // 4. Validation & Final Answer
    const robinsonSize = robinsonData.size;
    const santaClaraSize = santaClaraData.size;

    if (robinsonSize === 0 || santaClaraSize === 0) {
        console.log(`Image collection size for Robinson Crusoe: ${robinsonSize}`);
        console.log(`Image collection size for Santa Clara: ${santaClaraSize}`);
        console.log('C1');
        return;
    }

    const robinsonNdvi = robinsonData.ndvi.getInfo();
    const robinsonPixels = robinsonData.pixels.getInfo();
    const santaClaraNdvi = santaClaraData.ndvi.getInfo();
    const santaClaraPixels = santaClaraData.pixels.getInfo();

    console.log(`Robinson Crusoe: Images found: ${robinsonSize}, Mean NDVI: ${robinsonNdvi ? robinsonNdvi.toFixed(3) : 'N/A'}, Valid Pixels: ${robinsonPixels}`);
    console.log(`Santa Clara: Images found: ${santaClaraSize}, Mean NDVI: ${santaClaraNdvi ? santaClaraNdvi.toFixed(3) : 'N/A'}, Valid Pixels: ${santaClaraPixels}`);

    if (robinsonPixels === 0 || santaClaraPixels === 0) {
        console.log('C2');
        return;
    }

    if (robinsonNdvi === null || santaClaraNdvi === null) {
        console.log('C3');
        return;
    }

    if (robinsonNdvi > santaClaraNdvi) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(e);
    console.log('D');
});
